 1	// Review-fixture integration. External boundary monitor is supplied by the system owner.
 2	package compare_idma_state_pkg;
 3	  typedef struct packed {
 4	    logic [7:0] payload;
 5	    logic [3:0] tag;
 6	    logic poison;
 7	  } lane_t;
 8	  typedef lane_t [2:0] beat_t;
 9	endpackage
10	
11	module compare_idma_state (
12	  input logic clk_i,
13	  input logic rst_ni,
14	  input logic clear_packet_i,
15	  input logic flush_packet_i,
16	  input compare_idma_state_pkg::beat_t data_i,
17	  input logic valid_i,
18	  output logic ready_o,
19	  output compare_idma_state_pkg::beat_t data_o,
20	  output logic valid_o,
21	  input logic ready_i,
22	  output logic [2:0] packet_usage_o
23	);
24	  import compare_idma_state_pkg::*;
25	  beat_t lane_data;
26	  logic [2:0] lane_valid, lane_ready;
27	  logic packet_ready;
28	
29	  assign ready_o = &lane_ready;
30	
31	  idma_dataflow_element #(
32	    .BufferDepth(5), .StrbWidth(3), .strb_t(logic [2:0]), .byte_t(lane_t)
33	  ) i_dataflow (
34	    .clk_i, .rst_ni, .data_i,
35	    .valid_i({3{valid_i}}), .ready_o(lane_ready),
36	    .data_o(lane_data), .valid_o(lane_valid), .ready_i({3{packet_ready}})
37	  );
38	
39	  cc_stream_fifo #(
40	    .Depth(5), .FallThrough(1'b1), .data_t(beat_t)
41	  ) i_packet_fifo (
42	    .clk_i, .rst_ni, .clr_i(clear_packet_i), .flush_i(flush_packet_i),
43	    .usage_o(packet_usage_o), .data_i(lane_data), .valid_i(&lane_valid),
44	    .ready_o(packet_ready), .data_o, .valid_o, .ready_i
45	  );
46	  idma_boundary_monitor i_boundary_monitor (.clk_i, .rst_ni);
47	endmodule
